package com.bank.validation.service;

import java.util.logging.Logger;

// Validates a code by folding digit squares; happy (reaches 1) is valid.
public class HappyCodeValidator {
    private static final Logger log = Logger.getLogger(HappyCodeValidator.class.getName());

    public boolean isHappy(int code) {
        int slow = code;
        int fast = code;

        do {
            slow = squareDigits(slow);              // one fold
            fast = squareDigits(squareDigits(fast)); // two folds
        } while (slow != fast);

        boolean happy = (slow == 1);
        if (happy) log.info(() -> "Code " + code + " is happy (valid).");
        else       log.warning(() -> "Code " + code + " is unhappy (cycles).");
        return happy;
    }

    // Sum of the squares of the digits of n.
    private int squareDigits(int n) {
        int sum = 0;
        while (n > 0) {
            int d = n % 10;   // last digit
            sum += d * d;     // square it
            n /= 10;          // strip it off
        }
        return sum;
    }
}
