package com.bank.validation;

import com.bank.validation.service.HappyCodeValidator;
import java.util.logging.Logger;

public class HappyCodeDemo {
    private static final Logger log = Logger.getLogger(HappyCodeDemo.class.getName());

    public static void main(String[] args) {
        HappyCodeValidator validator = new HappyCodeValidator();

        int happyCode = 19;   // 1^2+9^2=82 ... eventually 1
        int unhappyCode = 2;  // folds into a cycle, never 1

        log.info(() -> "19 valid: " + validator.isHappy(happyCode));
        log.info(() -> "2  valid: " + validator.isHappy(unhappyCode));
    }
}
